declare global {
  namespace Express {
    interface Request {
      /** Set by requireAuth from the better-auth session; only present on
       * authenticated requests. Opaque string ids, generated by better-auth. */
      userId?: string;
      /** The user's household, and the scope for every recipe/tag/category query.
       * Read fresh from the DB on each request rather than cached in the session
       * cookie, since joining or leaving a family changes it mid-session. */
      familyId?: number;
      /** Set by requireAuth alongside userId, from the same user row getSession
       * already fetches — lets controllers that only need these fields
       * (getMe, postAiChat) skip a redundant re-fetch. */
      user?: {
        id: string;
        email: string;
        locale: string;
        unitSystem: string;
        smallVolumes: string;
        jsonImportExportEnabled: boolean;
        familyId: number;
      };
    }
  }
}

export {};
